Get-Content -LiteralPath $Path | ForEach-Object {
  $idx++
  try { $o = $_ | ConvertFrom-Json -ErrorAction Stop } catch { return }
  if ($o.type -eq 'response_item') {
    $p=$o.payload
    if ($p.type -eq 'message') {
      $texts=@()
      foreach($c in $p.content){ if($c.text){$texts += $c.text} elseif($c.type -eq 'output_text' -and $c.text){$texts += $c.text} elseif($c.type -eq 'input_text' -and $c.text){$texts += $c.text} }
      if($texts.Count -gt 0){
        $text=($texts -join "`n")
        if($text.Length -gt 6000){$text=$text.Substring(0,6000)+'...[TRUNCATED]'}
        "--- line=$idx time=$($o.timestamp) role=$($p.role) phase=$($p.phase) ---"
        $text
      }
    } elseif ($p.type -eq 'function_call') {
      $args=$p.arguments
      if($args.Length -gt 1200){$args=$args.Substring(0,1200)+'...[TRUNCATED]'}
      "--- line=$idx time=$($o.timestamp) tool=$($p.namespace).$($p.name) ---"
      $args
    }
  } elseif ($o.type -eq 'event_msg' -and $o.payload.type -eq 'user_message') {
    $text=$o.payload.message
    if($text.Length -gt 6000){$text=$text.Substring(0,6000)+'...[TRUNCATED]'}
    "--- line=$idx time=$($o.timestamp) event_user ---"
    $text
  }
}
